local function C_a()
local script = G2L["a"];
	local button = script.Parent
	local player = game.Players.LocalPlayer
	local RunService = game:GetService("RunService")

	button.MouseButton1Click:Connect(function()
		local char = player.Character
		local tool
		for i,v in player:GetDescendants() do
			if v.Name == "SyncAPI" then tool = v.Parent end
		end
		if not tool then
			for i,v in game.ReplicatedStorage:GetDescendants() do
				if v.Name == "SyncAPI" then tool = v.Parent end
			end
		end
		if not tool then return end

		local remote = tool.SyncAPI.ServerEndpoint
		local function _(args)
			remote:InvokeServer(unpack(args))
		end

		local function CreatePart(cf, parent)
			_({"CreatePart", "Normal", cf, parent})
		end

		local function SetName(part, name)
			_({"SetName", {part}, name})
		end

		local function AddMesh(part)
			_({"CreateMeshes", {{Part = part}}})
		end

		local function SetMesh(part, meshid)
			_({"SyncMesh", {{Part = part, MeshId = "rbxassetid://"..meshid}}})
		end

		local function SetTexture(part, texid)
			_({"SyncMesh", {{Part = part, TextureId = "rbxassetid://"..texid}}})
		end

		local function MeshResize(part, size)
			_({"SyncMesh", {{Part = part, Scale = size}}})
		end

		local function SetLocked(part, bool)
			_({"SetLocked", {part}, bool})
		end

		local e = char.HumanoidRootPart.CFrame.x
		local f = char.HumanoidRootPart.CFrame.y
		local g = char.HumanoidRootPart.CFrame.z
		local baseCF = CFrame.new(math.floor(e), math.floor(f), math.floor(g)) + Vector3.new(0, 6, 0)

		CreatePart(baseCF, workspace)
		task.wait(0.3)

		local part
		for i, v in pairs(workspace:GetChildren()) do
			if v:IsA("BasePart") and v.CFrame.x == math.floor(e) and v.CFrame.z == math.floor(g) then
				part = v
				break
			end
		end

		if not part then return end

		SetName(part, " wdaf")
		AddMesh(part)
		SetMesh(part, "111891702759441")
		SetTexture(part, "93235195570267")
		MeshResize(part, Vector3.new(99999, 99999, 99999))
		SetLocked(part, true)

		local angle = 0
		RunService.Heartbeat:Connect(function(dt)
			if not part or not part.Parent then return end
			angle = (angle + 45 * dt) % 360
			_({"SyncMove", {{Part = part, CFrame = baseCF * CFrame.Angles(0, math.rad(angle), 0)}}})
		end)
	end)
end;
